<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driver\Rest\SnippetAllowController;
use Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driver\Rest\SnippetListController;
use Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driver\Rest\SnippetCreateController;
use Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driver\Rest\SnippetRetrieveController;
use Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driver\Rest\SnippetUpdateController;
use Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driver\Rest\SnippetDeleteController;
use Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driver\Rest\SnippetEnableController;
use Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driver\Rest\SnippetDisableController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Document\Snippet\Application\Service\Visibility\SnippetRestrictFilterToVisibility;
use Civi\Lughauth\Features\Document\Snippet\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Document\Snippet\Application\Policy\Fields\FixTenantExcludingRoot;
use Civi\Lughauth\Features\Document\Snippet\Application\Service\Visibility\SnippetCollectNonEditableFields;
use Civi\Lughauth\Features\Document\Snippet\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Document\Snippet\Application\Usecase\Create\SnippetCreateAllowDecision;
use Civi\Lughauth\Features\Document\Snippet\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Document\Snippet\Application\Usecase\Update\SnippetUpdateAllowDecision;
use Civi\Lughauth\Features\Document\Snippet\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Document\Snippet\Application\Usecase\Retrieve\SnippetRetrieveAllowDecision;
use Civi\Lughauth\Features\Document\Snippet\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Document\Snippet\Application\Usecase\List\SnippetListAllowDecision;
use Civi\Lughauth\Features\Document\Snippet\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Document\Snippet\Application\Usecase\Delete\SnippetDeleteAllowDecision;
use Civi\Lughauth\Features\Document\Snippet\Application\Policy\Allow\Enable\IsAuthenticatedEnableAllow;
use Civi\Lughauth\Features\Document\Snippet\Application\Usecase\Enable\SnippetEnableAllowDecision;
use Civi\Lughauth\Features\Document\Snippet\Application\Policy\Allow\Disable\IsAuthenticatedDisableAllow;
use Civi\Lughauth\Features\Document\Snippet\Application\Usecase\Disable\SnippetDisableAllowDecision;
use Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driven\SnippetReadRepositoryAdapter;
use Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driven\SnippetWriteRepositoryAdapter;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetReadGateway;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetWriteGateway;

class SnippetPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[SnippetReadGateway::class] = \DI\autowire(SnippetReadRepositoryAdapter::class);
        $def[SnippetWriteGateway::class] = \DI\autowire(SnippetWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/document/snippet', [$this, 'setRoutesForSnippet']);
        $collector->group('/api/me/acl/document/snippet', [$this, 'setRoutesForSnippetAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(SnippetRestrictFilterToVisibility::class, TenantAccesible::class);
        $listener->registerListener(SnippetCollectNonEditableFields::class, FixTenantExcludingRoot::class);
        $listener->registerListener(SnippetCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
        $listener->registerListener(SnippetUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
        $listener->registerListener(SnippetRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
        $listener->registerListener(SnippetListAllowDecision::class, IsAuthenticatedListAllow::class);
        $listener->registerListener(SnippetDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
        $listener->registerListener(SnippetEnableAllowDecision::class, IsAuthenticatedEnableAllow::class);
        $listener->registerListener(SnippetDisableAllowDecision::class, IsAuthenticatedDisableAllow::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("snippet", "list", "READ");
            $handler->registerResourceAction("snippet", "create", "WRITE");
            $handler->registerResourceAction("snippet", "retrieve", "READ");
            $handler->registerResourceAction("snippet", "update", "WRITE");
            $handler->registerResourceAction("snippet", "delete", "WRITE");
            $handler->registerResourceAction("snippet", "enable", "WRITE");
            $handler->registerResourceAction("snippet", "disable", "WRITE");

            $handler->registerResourceAttribute("snippet", "code", "MANAGE");
            $handler->registerResourceAttribute("snippet", "tenant", "MANAGE");
            $handler->registerResourceAttribute("snippet", "enabled", "MANAGE");
            $handler->registerResourceAttribute("snippet", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForSnippetAcl(RouteCollectorProxy $snippetGroup): void
    {
        $snippetGroup->get('', [SnippetAllowController::class, 'genericAllow']);
        $snippetGroup->get('/{uid}', [SnippetAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForSnippet(RouteCollectorProxy $snippetGroup): void
    {
        $snippetGroup->get('', [SnippetListController::class, 'list']);
        $snippetGroup->post('', [SnippetCreateController::class, 'create']);
        $snippetGroup->get('/{uid}', [SnippetRetrieveController::class, 'retrieve']);
        $snippetGroup->put('/{uid}', [SnippetUpdateController::class, 'update']);
        $snippetGroup->delete('/{uid}', [SnippetDeleteController::class, 'delete']);
        $snippetGroup->delete('', [SnippetDeleteController::class, 'deleteAllForQuery']);
        $snippetGroup->get('/~/delete-status/{uid}', [SnippetDeleteController::class, 'checkDeleteAllForQueryStatus']);
        $snippetGroup->patch('/~/enable', [SnippetEnableController::class, 'enableAllForQuery']);
        $snippetGroup->patch('/{uid}/enable', [SnippetEnableController::class, 'enable']);
        $snippetGroup->get('/~/enable-status/{uid}', [SnippetEnableController::class, 'checkEnableAllForQueryStatus']);
        $snippetGroup->patch('/~/disable', [SnippetDisableController::class, 'disableAllForQuery']);
        $snippetGroup->patch('/{uid}/disable', [SnippetDisableController::class, 'disable']);
        $snippetGroup->get('/~/disable-status/{uid}', [SnippetDisableController::class, 'checkDisableAllForQueryStatus']);
    }
}
